<template><view class="row"><picker class="picker" :range="['全部班级', ...classes.map(c => c.label)]" @change="onChange"><view>{{ selectedLabel }} ▼</view></picker><picker class="picker small" :range="['全部','未完成','已完成']" @change="$emit('scope', ['all','unfinished','completed'][$event.detail.value])"><view>{{ scopeLabel }} ▼</view></picker></view></template>
<script setup lang="ts">import { computed } from 'vue'; const p=defineProps<{classes?:any[];selected?:string;scope?:string}>(); const emit=defineEmits<{class:[id:string];scope:[scope:string]}>(); const classes=computed(()=>p.classes||[]); const selectedLabel=computed(()=>p.selected?classes.value.find(c=>c.id===p.selected)?.label||'全部班级':'全部班级'); const scopeLabel=computed(()=>({all:'全部',unfinished:'未完成',completed:'已完成'} as any)[p.scope||'all']); function onChange(e:any){emit('class',e.detail.value?classes.value[e.detail.value-1]?.id||'':'')}</script>
<style scoped>.row{display:flex;gap:18rpx;margin:18rpx 0}.picker{flex:1;background:#fff;border-radius:30rpx;padding:16rpx 24rpx;color:#555;font-size:24rpx}.small{flex:0 0 180rpx}</style>
